import { test } from 'node:test';
import { equal } from 'node:assert/strict';
import { isPostalCode } from './postal.mjs';

test('「3桁-4桁」の郵便番号は true', () => {
  equal(isPostalCode('150-0002'), true);
});

test('ハイフンなしは false', () => {
  equal(isPostalCode('1500002'), false);
});

test('桁数が足りないものは false', () => {
  equal(isPostalCode('150-002'), false);
});

test('空文字は false', () => {
  equal(isPostalCode(''), false);
});

