import { test } from 'node:test';
import { equal } from 'node:assert/strict';
import { isLeapYear } from './leap.mjs';

test('4で割り切れる年はうるう年', () => {
  equal(isLeapYear(2024), true);
});

test('4で割り切れない年は平年', () => {
  equal(isLeapYear(2023), false);
});

test('100で割り切れる年は平年', () => {
  equal(isLeapYear(1900), false);
});

test('400で割り切れる年はうるう年', () => {
  equal(isLeapYear(2000), true);
});
